import os
import json
import time
import requests
MESSAGING_ENDPOINT = os.environ.get('MESSAGING_URL', 'https://sms.internal.example.com/v1/messages')
MESSAGING_TOKEN = os.environ['MESSAGING_TOKEN']
WAITLIST_LOG_PATH = os.environ.get('WAITLIST_LOG_PATH', 'waitlist_notifications.json')

def notify_waitlist_table_ready(party_name: str, phone_number: str, party_size: int, table_label: str, hold_minutes: int) -> dict:
    message_text_for_guest = f'Hi {party_name}, your table for {party_size} is ready at table {table_label}. We will hold it for {hold_minutes} minutes.'
    request_payload_for_service = {'to': phone_number, 'body': message_text_for_guest, 'tag': 'waitlist_ready'}
    request_headers_for_service = {'Authorization': f'Bearer {MESSAGING_TOKEN}'}
    service_response = requests.post(MESSAGING_ENDPOINT, json=request_payload_for_service, headers=request_headers_for_service, timeout=10)
    service_response.raise_for_status()
    response_body_from_service = service_response.json()
    notification_records = {}
    if os.path.exists(WAITLIST_LOG_PATH):
        with open(WAITLIST_LOG_PATH, 'r') as log_file:
            notification_records = json.load(log_file)
    notification_records[phone_number] = {'party_name': party_name, 'table_label': table_label, 'hold_minutes': hold_minutes, 'notified_at': int(time.time()), 'message_id': response_body_from_service.get('id')}
    with open(WAITLIST_LOG_PATH, 'w') as log_file:
        json.dump(notification_records, log_file)
    return {'message_id': response_body_from_service.get('id'), 'status': response_body_from_service.get('status', 'queued')}
